// Connector holds an authenticated client for one interface.
type Connector struct {
	client *InterfaceClient
}

// Client returns the interface client.
func (c *Connector) Client() *InterfaceClient {
	return c.client
}

// NewConnector constructs a Connector for the given interface.
func NewConnector(interfaceID string, creds connector.Credentials, config map[string]string, httpClient *http.Client) (*Connector, error) {
	switch interfaceID {
	case "oauth":
	default:
		return nil, fmt.Errorf("%w: %q", errInterfaceNotConfigured, interfaceID)
	}

	bc, ok := creds.(connector.BearerCredentials)
	if !ok {
		return nil, fmt.Errorf("google-youtube: interface %q: %w: got %T, want connector.BearerCredentials", interfaceID, connector.ErrCredentialType, creds)
	}

	if bc.Token == "" {
		return nil, fmt.Errorf("google-youtube: interface %q: %w: empty token", interfaceID, connector.ErrMissingCredential)
	}

	ts := oauth2.StaticTokenSource(&oauth2.Token{AccessToken: bc.Token})

	var opts []option.ClientOption
	if httpClient != nil {
		httpClient = &http.Client{
			Transport: &oauth2.Transport{
				Source: ts,
				Base:   httpClient.Transport,
			},
		}
		opts = []option.ClientOption{option.WithHTTPClient(httpClient)}
	} else {
		opts = []option.ClientOption{option.WithTokenSource(ts)}
	}

	svc, err := target.NewService(context.Background(), opts...)
	if err != nil {
		return nil, fmt.Errorf("creating %s client: %w", interfaceID, err)
	}

	return &Connector{client: &InterfaceClient{svc: svc}}, nil
}

// BuildCredentials builds the Credentials the named interface authenticates
// with from the platform's stored credential keys. It returns nil credentials
// for interfaces that need none.
func BuildCredentials(interfaceID string, stored map[string]string) (connector.Credentials, error) {
	switch interfaceID {
	case "oauth":
		secret, err := storedCredential(stored, interfaceID, "access_token")
		if err != nil {
			return nil, err
		}

		return connector.BearerCredentials{Token: secret}, nil
	default:
		return nil, fmt.Errorf("google-youtube: %w: %q", connector.ErrUnknownInterface, interfaceID)
	}
}

// storedCredential returns the stored value under key, or an error naming the
// key when it is missing or empty.
func storedCredential(stored map[string]string, interfaceID, key string) (string, error) {
	if v := stored[key]; v != "" {
		return v, nil
	}

	return "", fmt.Errorf("google-youtube: interface %q: %w %q", interfaceID, connector.ErrMissingCredential, key)
}
